/* Background motion is decoupled from the 3D object's orbit controls. */
(()=>{const reduce=matchMedia('(prefers-reduced-motion: reduce)'),backdrop=document.querySelector('.motion-backdrop');let pending=false;function paint(){pending=false;backdrop.style.setProperty('--drift',reduce.matches?'0px':Math.round(scrollY*.065)+'px');}addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(paint);}},{passive:true});reduce.addEventListener('change',paint);paint();if('IntersectionObserver' in window)new IntersectionObserver(entries=>{if(entries[0].isIntersecting){document.querySelectorAll('.header nav a').forEach((a,i)=>a.classList.toggle('active',i===0));}},{threshold:.5}).observe(document.querySelector('.intro'));})();
